Task: Push the orange puck so that its centre ends up inside the green circle. The puck is too wide to grasp.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     """
  5|     Push the orange puck so its centre ends inside the green circular zone.
  6|     The puck cannot be grasped, so we approach it from the opposite side of the target,
  7|     move the gripper over the puck, then push forward at table height.
  8|     """
  9|     max_attempts = 2
 10|     for attempt in range(max_attempts):
 11|         try:
 12|             obs = robot.observe()
 13|             puck = obs["objects"]["puck"]
 14|             target = obs["fixtures"]["target"]
 15| 
 16|             puck_pos = puck["pos"]          # [x, y, z]
 17|             target_pos = target["pos"]      # [x, y, 0]
 18|             puck_radius = puck["size"]["radius"]  # assume size dict has radius
 19| 
 20|             # Vector from puck to target
 21|             dx = target_pos[0] - puck_pos[0]
 22|             dy = target_pos[1] - puck_pos[1]
 23|             dist = math.hypot(dx, dy)
 24|             if dist < 1e-4:  # already on target
 25|                 return True
 26|             ux = dx / dist
 27|             uy = dy / dist
 28| 
 29|             # Stand‑off distance: puck radius + small clearance
 30|             offset = puck_radius + 0.01
 31|             behind_x = puck_pos[0] - offset * ux
 32|             behind_y = puck_pos[1] - offset * uy
 33| 
 34|             # Heights: high enough to clear puck, then low for pushing
 35|             stand_off_z = 0.05   # tool point height to avoid hitting puck
 36|             push_z = 0.02        # tool point height for contact (fingertips ~0.0075 m)
 37| 
 38|             # 1. Move to stand‑off point above the puck
 39|             robot.move_to(behind_x, behind_y, stand_off_z, speed=0.15)
 40| 
 41|             # 2. Lower to pushing height while staying behind the puck
 42|             robot.move_to(behind_x, behind_y, push_z, speed=0.07)
 43| 
 44|             # 3. Push forward to the target (no extra margin)
 45|             push_dist = dist + offset
 46|             push_x = puck_pos[0] + ux * push_dist
 47|             push_y = puck_pos[1] + uy * push_dist
 48|             robot.move_to(push_x, push_y, push_z, speed=0.07)
 49| 
 50|             # 4. Lift slightly to avoid dragging the puck back
 51|             robot.move_by(dz=0.02, speed=0.1)
 52| 
 53|             # 5. Verify success
 54|             obs2 = robot.observe()
 55|             puck_pos2 = obs2["objects"]["puck"]["pos"]
 56|             dx2 = puck_pos2[0] - target_pos[0]
 57|             dy2 = puck_pos2[1] - target_pos[1]
 58|             if math.hypot(dx2, dy2) <= target["radius"]:
 59|                 return True
 60| 
 61|             # If not successful, loop will retry with fresh perception
 62|         except Exception as e:
 63|             robot.log("Exception during push attempt:", e)
 64|             continue
 65| 
 66|     return False

